import React, { useEffect } from 'react';
import { ImageBackground, Pressable, StyleSheet, Text, View } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import Animated, { Easing, cancelAnimation, useAnimatedStyle, useSharedValue, withRepeat, withTiming } from 'react-native-reanimated';
import { HERO_SUB, HERO_TITLE, heroMotion } from './hero';

// Original art, generated by tools/art/frequencies_hero.py (Metro picks @2x or @3x).
const HERO_ART = require('../assets/hero/frequencies-hero.png');

/** Full-width featured card for the Frequencies category, with a slow breathing glow. */
export function FrequenciesHero({ selected, reduceMotion, onPress }: {
  selected: boolean; reduceMotion: boolean; onPress: () => void;
}) {
  const m = heroMotion(reduceMotion);
  const glow = useSharedValue(m.rest);

  useEffect(() => {
    if (!m.breathe) {
      cancelAnimation(glow);
      glow.value = m.rest;
      return;
    }
    glow.value = m.min;
    glow.value = withRepeat(withTiming(m.max, { duration: m.periodMs / 2, easing: Easing.inOut(Easing.sin) }), -1, true);
    return () => cancelAnimation(glow);
  }, [m.breathe, m.min, m.max, m.rest, m.periodMs, glow]);

  const glowStyle = useAnimatedStyle(() => ({ opacity: glow.value }));

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${HERO_TITLE}. ${HERO_SUB}`}
      accessibilityState={{ selected }}
      testID="frequencies-hero"
      style={styles.wrap}
    >
      <Animated.View pointerEvents="none" style={[styles.glow, glowStyle]} testID="frequencies-hero-glow" />
      <ImageBackground
        source={HERO_ART}
        resizeMode="cover"
        style={[styles.card, selected && styles.cardOn]}
        imageStyle={styles.art}
        testID="frequencies-hero-art"
      >
        {/* Keeps the text readable over the art: indigo fading out to the right. */}
        <LinearGradient
          colors={['rgba(10,12,46,0.85)', 'rgba(10,12,46,0.35)', 'rgba(10,12,46,0)']}
          locations={[0, 0.45, 0.7]}
          start={{ x: 0, y: 0.5 }}
          end={{ x: 1, y: 0.5 }}
          style={StyleSheet.absoluteFill}
        />
        <View style={styles.text}>
          <Text style={styles.title}>{HERO_TITLE}</Text>
          <Text style={styles.sub} numberOfLines={3}>{HERO_SUB}</Text>
        </View>
        <Text style={styles.chev}>›</Text>
      </ImageBackground>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  wrap: { marginHorizontal: 16, marginTop: 4, marginBottom: 4 },
  glow: {
    position: 'absolute', top: -4, left: -4, right: -4, bottom: -4, borderRadius: 26,
    backgroundColor: 'rgba(167,139,250,0.35)',
    shadowColor: '#a78bfa', shadowOpacity: 0.9, shadowRadius: 18, shadowOffset: { width: 0, height: 0 },
  },
  card: { flexDirection: 'row', alignItems: 'center', aspectRatio: 400 / 132, borderRadius: 22, overflow: 'hidden', paddingHorizontal: 18, borderWidth: 1, borderColor: 'rgba(196,181,253,0.35)', backgroundColor: '#0a0c2e' },
  art: { borderRadius: 22 },
  text: { width: '52%' },
  cardOn: { borderColor: '#f5f3ff', borderWidth: 1.5 },
  title: { color: '#f5f3ff', fontSize: 20, fontWeight: '800', textShadowColor: 'rgba(0,0,0,0.6)', textShadowRadius: 6 },
  sub: { color: '#ddd6fe', fontSize: 12, marginTop: 3, lineHeight: 16 },
  chev: { position: 'absolute', right: 14, top: 10, color: '#f5f3ff', fontSize: 26, fontWeight: '300' },
});
